use gpui::{
    AppContext, Bounds, Context, IntoElement, MouseButton, MouseDownEvent, Render, Role,
    StyledText, TextLayout, Window, canvas, div, fill, prelude::*, px, rgb, size, text,
};

const PARAGRAPH: &str = "Café — Straße — click a wrapped line to inspect its UTF-8 byte index.";

struct HitTest {
    index: usize,
    hit: bool,
}

fn component(_window: &mut Window, cx: &mut gpui::App) -> gpui::Entity<HitTest> {
    cx.new(|_cx| HitTest {
        index: 0,
        hit: false,
    })
}

impl Render for HitTest {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let text = StyledText::new(PARAGRAPH);
        let input_layout = text.layout().clone();
        let marker_layout = text.layout().clone();
        let index = self.index;
        div()
            .size_full()
            .flex()
            .flex_col()
            .items_center()
            .justify_center()
            .gap_4()
            .bg(rgb(0xf7f6f2))
            .text_color(rgb(0x202b29))
            .child(
                div()
                    .id("paragraph")
                    .role(Role::Label)
                    .aria_label(PARAGRAPH)
                    .relative()
                    .flex()
                    .flex_col()
                    .w(px(280.))
                    .text_size(px(18.))
                    .line_height(px(28.))
                    .cursor_text()
                    .on_mouse_down(
                        MouseButton::Left,
                        cx.listener(move |this, event: &MouseDownEvent, _window, cx| {
                            let result = input_layout.index_for_position(event.position);
                            this.hit = result.is_ok();
                            this.index = result.unwrap_or_else(|edge| edge);
                            cx.notify();
                        }),
                    )
                    .child(text)
                    .child(marker(marker_layout, index)),
            )
            .child(text!(format!(
                "Byte {} / {} · {}",
                self.index,
                PARAGRAPH.len(),
                if self.hit {
                    "cluster hit"
                } else {
                    "visual edge"
                },
            )))
    }
}

fn marker(layout: TextLayout, index: usize) -> impl IntoElement {
    canvas(
        move |_bounds, _window, _cx| {
            // The preceding text child has already completed prepaint.
            (layout.position_for_index(index), layout.line_height())
        },
        |_bounds, (position, height), window, _cx| {
            if let Some(position) = position {
                window.paint_quad(fill(
                    Bounds::new(position, size(px(2.), height)),
                    rgb(0xd04736),
                ));
            }
        },
    )
    .absolute()
    .inset_0()
}

pub fn main() {
    support::run(component);
}

mod support {
    //! Platform setup shared by the walkthroughs; each downloaded main.rs includes it.
    use gpui::{App, Entity, Render, Window, WindowOptions};

    pub fn run<V: Render>(build: impl FnOnce(&mut Window, &mut App) -> Entity<V> + 'static) {
        #[cfg(not(target_family = "wasm"))]
        gpui_platform::application().run(move |cx| {
            cx.on_window_closed(|cx, _| {
                if cx.windows().is_empty() {
                    cx.quit();
                }
            })
            .detach();
            open(build, cx);
        });

        #[cfg(target_family = "wasm")]
        {
            use gpui::{Application, ApplicationHandle};
            use std::{cell::RefCell, rc::Rc, sync::Arc};
            thread_local! {
                static APPLICATION: RefCell<Option<ApplicationHandle>> = const { RefCell::new(None) };
            }
            gpui_web::init_logging();
            let platform = Rc::new(gpui_web::WebPlatform::new(false));
            let client = Arc::new(platform.fetch_http_client());
            let handle = Application::with_platform(platform)
                .with_http_client(client)
                .run_embedded(move |cx| {
                    use std::borrow::Cow;
                    cx.text_system()
                        .add_fonts(vec![Cow::Borrowed(include_bytes!(
                            "../../../assets/fonts/ibm-plex-sans/IBMPlexSans-Regular.ttf"
                        ) as &[u8])])
                        .expect("load the preview font");
                    open(build, cx);
                });
            APPLICATION.with(|slot| *slot.borrow_mut() = Some(handle));
            if let Some(window) = web_sys::window() {
                if let Ok(Some(parent)) = window.parent() {
                    let _ = parent
                        .post_message(&wasm_bindgen::JsValue::from_str("gpui-preview-ready"), "*");
                }
            }
        }
    }

    fn open<V: Render>(build: impl FnOnce(&mut Window, &mut App) -> Entity<V> + 'static, cx: &mut App) {
        cx.open_window(WindowOptions::default(), build)
            .expect("open the example window");
        cx.activate(true);
    }
}
